'use server';

import { adminDb } from '@/firebase/admin';
import { revalidatePath } from 'next/cache';

interface HomePageSettings {
    featuredProjectId: string;
}

/**
 * Updates the homepage settings in Firestore.
 * @param settings The new homepage settings.
 */
export async function updateHomepageSettings(settings: HomePageSettings) {
  try {
    const settingsDocRef = adminDb.collection('homepage').doc('settings');
    await settingsDocRef.set(settings, { merge: true });
    revalidatePath('/admin');
    revalidatePath('/');
  } catch (error) {
    console.error('Error updating homepage settings:', error);
    throw new Error('Could not update homepage settings.');
  }
}
