'use server';

import * as admin from 'firebase-admin';
import 'server-only';

// This function initializes the Firebase Admin SDK.
// It checks if the app is already initialized to prevent errors.
const initializeAdminApp = () => {
  if (admin.apps.length > 0) {
    return admin.app();
  }

  // Your service account credentials from the environment variable.
  const serviceAccount = process.env.FIREBASE_SERVICE_ACCOUNT;
  if (!serviceAccount) {
    throw new Error('FIREBASE_SERVICE_ACCOUNT environment variable is not set.');
  }

  const credentials = JSON.parse(serviceAccount);

  return admin.initializeApp({
    credential: admin.credential.cert(credentials),
  });
};

// Initialize the app and get the Firestore instance.
// These are exported for use in your server actions.
export const adminApp = initializeAdminApp();
export const adminDb = admin.firestore();
